const int MAXN = 3e5 + 5;
vector<int> adj[MAXN];
int dsu[MAXN], sz[MAXN], on[MAXN], ans[MAXN];

int find(int x) {
    return dsu[x] < 0 ? x : dsu[x] = find(dsu[x]);
}

void merge(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    if (sz[x] < sz[y]) swap(x, y);
    dsu[y] = x;
    sz[x] += sz[y];
}

