#include <bits/stdc++.h>
using namespace std;

bool bfs(int n, vector<vector<char>> &grid, int choose){
    queue<pair<int, int>> q;
    q.push({0, 0});
    vector<vector<bool>> visited(n, vector<bool>(n, false));
    visited[0][0] = true;

    while(!q.empty()){
        int x = q.front().first;
        int y = q.front().second;
        q.pop();

        if(x == n-1 && y == n-1){
            return true;
        }

        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};

        for(int i = 0; i < 4; i++){
            int nx = x + dx[i];
            int ny = y + dy[i];
            if(nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]){
                if((nx == 0 && ny == 0) || (nx == n-1 && ny == n-1) || grid[nx][ny] - '0' == choose){
                    visited[nx][ny] = true;
                    q.push({nx, ny});
                }
            }
        }
    }

    return false;
}

