#include <bits/stdc++.h>
using namespace std;

const int MAXN = 3005;

vector<int> adj[MAXN];
bool visited[MAXN];
int sz[MAXN];
double dp[MAXN];

void dfs(int u, int p) {
    sz[u] = 1;
    visited[u] = true;
    for (int v : adj[u]) {
        if (v != p && !visited[v]) {
            dfs(v, u);
            sz[u] += sz[v];
        }
    }
}

double solve(int n) {
    if (n <= 1) return 0.0;
    double ans = n;
    fill(visited, visited + n, false);
    dfs(0, -1);
    fill(dp, dp + n, 0.0);
    for (int i = 0; i < n; ++i) {
        vector<double> contrib;
        for (int v : adj[i]) {
            if (sz[v] > 0) {
                contrib.push_back(sz[v] / (double)(n - 1));
            }
        }
        if (contrib.size() > 0) {
            double sum = 0.0;
            for (double x : contrib) sum += x;
            for (int v : adj[i]) {
                if (sz[v] > 0) {
                    double p = sz[v] / (double)(n - 1);
                    dp[i] += p * (1 + dp[v] + solve(sz[v]) - solve(n) * p);
                }
            }
        }
    }
    double EXPECT = 0.0;
    for (int i = 0; i < n; ++i) {
        EXPECT += dp[i];
    }
    return ans + EXPECT / n;
}

