int main() {
    string input;
    getline(cin, input);
    stringstream ss(input);
    vector<int> numbers;
    vector<char> operations;
    string token;

    while (getline(ss, token, ' ')) {
        if (token == "?" || token == "+" || token == "-" || token == "=") {
            if (token == "?" || token == "+" || token == "-") {
                numbers.push_back(-1);
                if (token == "+") operations.push_back('+');
                if (token == "-") operations.push_back('-');
            } else if (token == "=") {
                break;
            }
        }
    }

    int n;
    ss >> n;

    int q_count = numbers.size();
    if (q_count == 0){
        if (n == 0) cout << "Possible\n0 = 0";
        else cout << "Impossible";
        return 0;
    }

    if (q_count == 1){
        if (n > 0) cout << "Possible\n" << n << " = " << n;
        else cout << "Impossible";
        return 0;
    }

    bool possible = false;
    for (int i = 1; i <= n && !possible; ++i) {
        for (int j = 1; j <= n && !possible; ++j) {
            for (int k = 1; k <= n && !possible; ++k) {
                for (int l = 1; l <= n && !possible; ++l) {
                    for (int m = 1; m <= n && !possible; ++m) {
                        numbers[0] = i, numbers[1] = j, numbers[2] = k, numbers[3] = l, numbers[4] = m;
                        int result = numbers[0];
                        for (int op_idx = 0; op_idx < operations.size(); ++op_idx) {
                            if (operations[op_idx] == '+') {
                                result += numbers[op_idx + 1];
                            } else if (operations[op_idx] == '-') {
                                result -= numbers[op_idx + 1];
                            }
                        }
                        if (result == n) {
                            possible = true;
                            break;
                        }
                    }
                }
            }
        }
    }

    if (possible) {
        cout << "Possible\n";
        for (int i = 0; i < q_count - 1; ++i) {
            cout << numbers[i] << " " << operations[i] << " ";
        }
        cout << numbers.back() << " = " << n;
    } else {
        cout << "Impossible";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Road {
    int u, v;
    long long w;
    bool operator<(const Road& other) const {
        return w < other.w;
    }
};

int find(int x, vector<int>& parent) {
    if (parent[x] == x) return x;
    return parent[x] = find(parent[x], parent);
}

void unite(int x, int y, vector<int>& parent, vector<int>& rank) {
    int rootX = find(x, parent);
    int rootY = find(y, parent);
    if (rootX == rootY) return;
    if (rank[rootX] > rank[rootY]) {
        parent[rootY] = rootX;
    } else if (rank[rootX] < rank[rootY]) {
        parent[rootX] = rootY;
    } else {
        parent[rootY] = rootX;
        rank[rootX]++;
    }
}

int main() {
    int n, m, q;
    cin >> n >> m >> q;
    vector<Road> roads(m);
    for (int i = 0; i < m; i++) {
        cin >> roads[i].u >> roads[i].v >> roads[i].w;
        roads[i].u--;
        roads[i].v--;
    }
    vector<pair<int, int>> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].first >> queries[i].second;
        queries[i].first--;
        queries[i].second--;
    }
    vector<long long> answers(q, -1);
    for (int i = 0; i < m; i++) {
        vector<int> parent(n);
        vector<int> rank(n, 0);
        for (int j = 0; j < n; j++) parent[j] = j;
        for (int j = i; j < m; j++) {
            unite(roads[j].u, roads[j].v, parent, rank);
            for (int k = 0; k < q; k++) {
                if (queries[k].first > i || queries[k].second < j) continue;
                int rootU = find(roads[queries[k].first].u, parent);
                int rootV = find(roads[queries[k].second].v, parent);
                int rootW = find(roads[queries[k].first].v, parent);
                int rootX = find(roads[queries[k].second].u, parent);
                if (rootU == rootV || rootW == rootX) {
                    if (answers[k] == -1 || answers[k] > roads[j].w) {
                        answers[k] = roads[j].w;
                    }
                }
            }
        }
    }
    for (int i = 0; i < q; i++) {
        cout << answers[i] << "\n";
    }
}

