using namespace std;

int dx[] = {-2, -1, 0, 1, 2};
int dy[] = {-2, -1, 0, 1, 2};

bool canSatisfy(int N, vector<vector<int>>& schedule) {
    vector<vector<int>> rain(4, vector<int>(4, 1));
    rain[1][1] = rain[1][2] = rain[2][1] = rain[2][2] = 1;

    for (int day = 1; day < N; ++day) {
        bool valid = false;
        for (int x = 0; x < 4; ++x) {
            for (int y = 0; y < 4; ++y) {
                bool possible = true;
                for (int i = 0; i < 5; ++i) {
                    for (int j = 0; j < 5; ++j) {
                        int nx = x + dx[i];
                        int ny = y + dy[j];
                        if (nx >= 0 && nx < 4 && ny >= 0 && ny < 4) {
                            if (schedule[day][nx * 4 + ny] && (abs(nx - x) > 1 || abs(ny - y) > 1)) {
                                possible = false;
                            }
                        }
                    }
                }
                if (possible) {
                    valid = true;
                    rain = vector<vector<int>>(4, vector<int>(4, 0));
                    for (int i = 0; i < 5; ++i) {
                        for (int j = 0; j < 5; ++j) {
                            int nx = x + dx[i];
                            int ny = y + dy[j];
                            if (nx >= 0 && nx < 4 && ny >= 0 && ny < 4) {
                                rain[nx][ny] = 1;
                            }
                        }
                    }
                    break;
                }
            }
            if (valid) break;
        }
        if (!valid) return false;
    }

    return true;
}

