const int MAXN = 100005;
vector<int> adj[MAXN];
int weight[MAXN];
int par[MAXN], sz[MAXN], perf[MAXN];
bool removed[MAXN];
int n, m;

int getParent(int x) {
    while (par[x] != x) x = par[x];
    return x;
}

void merge(int x, int y) {
    x = getParent(x);
    y = getParent(y);
    if (x != y) {
        if(sz[x] < sz[y]) swap(x, y);
        par[y] = x;
        sz[x] += sz[y];
        perf[x] += perf[y];
    }
}

int main(){
