        adj[v].push_back(u);
    }
    for(int i=n; i>=1; i--){
        removed[i] = true;
        for(auto &j: adj[i]){
            if(!removed[j]) merge(i, j);
        }
        int p = getParent(i);
        cout << perf[p] << "\n";
    }
}

