typedef long long ll;

bool canTransform(ll ax, ll ay, ll bx, ll by, ll cx, ll cy) {
    for(int i = 0; i < 4; ++i) {
        ll dx = ax - bx;
        ll dy = ay - by;
        if(dx % cx == 0 && dy % cy == 0 && dx / cx == dy / cy) return true;
        if(-dx % cx == 0 && dy % cy == 0 && -dx / cx == dy / cy) return true;
        if(dx % cx == 0 && -dy % cy == 0 && dx / cx == -dy / cy) return true;
        if(-dx % cx == 0 && -dy % cy == 0 && -dx / cx == -dy / cy) return true;
        swap(ax, ay);
        ax = -ax;
    }
    return false;
}

