    vector<Edge> all_edges;
    for(int i=0; i<m; i++){
        int u, v;
        long long w;
        cin >> u >> v >> w;
        u--, v--;
        all_edges.push_back({u, v, w});
        all_edges.push_back({v, u, w});
    }
    for(int i=0; i<q; i++){
        int a, b;
        cin >> a >> b;
        a--, b--;
        if(a == b){
            cout << 0 << "\n";
            continue;
        }
        int lo = 0, hi = (int)1e9, res = -1;
        while(lo <= hi){
            int mid = (lo + hi) / 2;
            if(check_capacity(n, m, k, all_edges, mid, a, b)){
                res = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        cout << res << "\n";
    }
}

