typedef long long ll;

const int MAXN = 1005;
const ll INF = 1e18;

vector<pair<int, ll>> adj[MAXN];
vector<tuple<int, int, ll>> edges;
int n, m, s, t;
ll L;

bool spfa(ll mid) {
    vector<ll> dist(n, INF);
    vector<int> cnt(n, 0);
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (auto &e : adj[u]) {
            int v = e.first;
            ll w = e.second;
            if (w == 0) w = mid;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                cnt[v] = cnt[u] + 1;
                if (cnt[v] >= n) return false;
                q.push(v);
            }
        }
    }
    return dist[t] <= L;
}

int main(){
