        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }
    ll lo = 1, hi = 1e18, ans = -1;
    while(lo <= hi){
        ll mid = (lo + hi) / 2;
        if(spfa(mid)){
            ans = mid;
            hi = mid - 1;
        }
        else lo = mid + 1;
    }
    if(ans == -1){
        cout << "NO\n";
        return 0;
    }
    cout << "YES\n";
    for(auto &[u, v, w] : edges){
        if(w == 0) w = ans;
        cout << u << " " << v << " " << w << "\n";
    }
}

