    for(auto &x: f) cin >> x;
    cout << fixed << setprecision(6) << solve(f, n) << "\n";
    for(int i=0;i<r;i++){
        int z, g;
        cin >> z >> g;
        f[z] = g;
        cout << fixed << setprecision(6) << solve(f, n) << "\n";
