    for(int i=0; i<n; i++){
        if(s[i] == '0'){
            if(extra_zero && zero < half_q){
                zero++;
                prefix[i+1] = prefix[i] + 1;
            } else if(zero >= half_q){
                one++;
                prefix[i+1] = prefix[i] - 1;
            } else {
                zero++;
                prefix[i+1] = prefix[i] + 1;
            }
        } else if(s[i] == '1'){
            if(zero >= half_q){
                one++;
                prefix[i+1] = prefix[i] - 1;
            } else if(one < half_q){
                one++;
                prefix[i+1] = prefix[i] - 1;
            } else {
                zero++;
                prefix[i+1] = prefix[i] + 1;
            }
        } else {
            if(zero < half_q){
                zero++;
                prefix[i+1] = prefix[i] + 1;
            } else if(zero >= half_q + extra_zero){
                one++;
                prefix[i+1] = prefix[i] - 1;
            } else {
                if(one < half_q){
                    one++;
                    prefix[i+1] = prefix[i] - 1;
                } else {
                    zero++;
                    prefix[i+1] = prefix[i] + 1;
                }
            }
        }
    }
