char grid[55][55];
double mAx, mAy, mT;

void calc(int x, int y, double ma, double mb, double mx) {
    double m = 0, cx = 0, cy = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (grid[i][j] == 'A') {
                m += ma;
                cx += ma * (i + 0.5);
                cy += ma * (j + 0.5);
            } else if (grid[i][j] == 'B') {
                m += mb;
                cx += mb * (i + 0.5);
                cy += mb * (j + 0.5);
            } else if (grid[i][j] == 'X') {
                m += mx;
                cx += mx * (i + 0.5);
                cy += mx * (j + 0.5);
            }
        }
    }
    if (m > 0) {
        double nx = cx / m, ny = cy / m;
        if (floor(nx) != nx && floor(ny) != ny) {
            int ix = (int)nx, jx = (int)ny;
            if (grid[ix][jx] != '.') {
                mAx += ma;
                mAy += mb;
                mT += mx;
            }
        }
    }
}

