        for (char c: r[i]) {
            int cc = c - 'a';
            bool found = false;
            for (int j = pos[cc].size() - 1; j >= 0; j--) {
                if (pos[cc][j] >= last[i]) {
                    last[i] = pos[cc][j] + 1;
                    pos[cc].erase(pos[cc].begin() + j);
                    found = true;
                    break;
                }
            }
            if (!found) {
                return false;
            }
        }
        for (int c = 0; c < MAXC; c++) {
            pos[c].resize(0);
        }
        for (int j = 0; j < n; j++) {
            pos[s[j] - 'a'].push_back(j);
        }
    }
    return true;
}

