void solve(vector<int>& a, vector<int>& depth, int l, int r, int d) {
    if (l > r) return;
    int max_idx = l;
    for (int i = l + 1; i <= r; ++i) {
        if (a[i] > a[max_idx]) {
            max_idx = i;
