ll maxLCM(ll n) {
    ll maxlcm = 1;
    for (ll i = n; i >= max(1LL, n - 2); --i) {
        for (ll j = n; j >= max(1LL, n - 2); --j) {
            for (ll k = n; k >= max(1LL, n - 2); --k) {
                maxlcm = max(maxlcm, lcm(lcm(i, j), k));
            }
        }
    }
    return maxlcm;
}

