    bfs(1);

    int count = 0;
    vector<pair<pair<int, int>, pair<int, int>>> plan;
    for (int i = 2; i <= n; ++i) {
        if (!visited[i]) {
            for (auto& edge : edges) {
                if (!visited[edge.first] && !visited[edge.second]) {
                    plan.push_back({edge, {1, i}});
                    visited[edge.first] = visited[edge.second] = true;
                    ++count;
