        while(t > 0){
            if(w == 'U'){
                auto it = upper_bound(v[y].begin(), v[y].end(), make_pair(x,0LL));
                if(it == v[y].begin()){
                    long long steps = min(t, (long long)x);
                    x -= steps;
                    t -= steps;
                }
                else{
                    --it;
                    long long end = it->second;
                    long long steps = min(t, end - x);
                    x += steps;
                    t -= steps;
                    if(t == 0) break;
                    y += 1;
                    if(y > b){
                        y = b;
                        break;
                    }
                    w = 'R';
                }
            }
            else if(w == 'D'){
                auto it = upper_bound(v[y].begin(), v[y].end(), make_pair(x,0LL));
                if(it == v[y].begin()){
                    long long steps = min(t, (long long)x);
                    x -= steps;
                    t -= steps;
                }
                else{
                    --it;
                    long long end = it->second;
                    long long steps = min(t, end - x);
                    x += steps;
                    t -= steps;
                    if(t == 0) break;
                    y -= 1;
                    if(y < 0){
                        y = 0;
                        break;
                    }
                    w = 'L';
                }
            }
            else if(w == 'L'){
                auto it = upper_bound(h[x].begin(), h[x].end(), make_pair(y,0LL));
                if(it == h[x].begin()){
                    long long steps = min(t, (long long)y);
                    y -= steps;
                    t -= steps;
                }
                else{
                    --it;
                    long long end = it->second;
                    long long steps = min(t, end - y);
                    y += steps;
                    t -= steps;
                    if(t == 0) break;
                    x -= 1;
                    if(x < 0){
                        x = 0;
                        break;
                    }
                    w = 'D';
                }
            }
            else if(w == 'R'){
                auto it = upper_bound(h[x].begin(), h[x].end(), make_pair(y,0LL));
                if(it == h[x].begin()){
                    long long steps = min(t, (long long)y);
