    int max_q = *max_element(q.begin(), q.end());
    sieve(max_q);
    sort(q.begin(), q.end());
    vector<int> primes;
    vector<int> powers;
    for(int i = 0; i < N;){
        int p = q[i++];
        int cnt = 1;
        if(i < N && q[i] <= 10 && p*q[i] <= max_q && spf[p*q[i]] == p*q[i]){
            p *= q[i++];
            cnt = q[i++];
        }
        primes.push_back(p);
        powers.push_back(cnt);
    }
    if(primes.size() < N){
        cout << "0\n";
        return 0;
    }
    for(int i = 1; i < primes.size(); i++){
        if(primes[i-1] >= primes[i]){
            cout << "0\n";
            return 0;
        }
    }
    ll res = 1;
    for(auto &x: powers){
        res = (res * (x + 1)) % MOD;
    }
    cout << res << "\n";
}

