    while(lo <= hi){
        int mid = (lo + hi) / 2;
        vector<ll> p = a;
        vector<ll> used(t, 0);
        bool ok = true;
        for(int h=0; h<t && ok; h++){
            ll capacity = (ll)mid * k;
            for(int i=0; i<n && ok; i++){
                if(p[i] > c[i]){
