                    p[i] -= take;
                    capacity -= take;
                }
            }
            if(!ok) break;
            for(int i=0; i<n; i++){
                p[i] += b[i];
            }
            if(capacity > 0){
                used[h] = min(mid, (int)(capacity/k));
                mid -= used[h];
            }
        }
        if(ok){
            ans = mid;
            hi = mid - 1;
        }
        else{
            lo = mid + 1;
        }
    }
