const int MAXN = 2e5 + 10;
const int MAXLOG = 64;

int n, q, A[MAXN];
int dp[MAXN][MAXLOG];

void precompute() {
    for(int i = 1; i <= n; i++) dp[i][0] = A[i];
    for(int j = 1; (1ll << j) <= MAXLOG; j++) {
        for(int i = 1; i <= n; i++) {
            if(dp[i][j - 1] == -1) dp[i][j] = -1;
            else dp[i][j] = dp[dp[i][j - 1]][j - 1];
        }
    }
}

int get(int x, long long m) {
    for(int j = MAXLOG - 1; j >= 0; j--) {
        if(m & (1ll << j)) {
            x = dp[x][j];
            if(x == -1) break;
        }
    }
    return x;
}

